data.minimal_example:
const source = '''
{{# names }}
  <div>{{ lastname }}, {{ firstname }}</div>
{{/ names }}
{{^ names }}
  <div>No names.</div>
{{/ names }}
{{! I am a comment. }}
''';
final template = Template(source, name: 'example');
final output = template.renderString({
  'names': [
    {'firstname': 'Greg', 'lastname': 'Lowe'},
    {'firstname': 'Bob', 'lastname': 'Johnson'},
  ],
});
